from __future__ import annotations

import bisect
import tempfile
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, List, Literal, Optional, Tuple

import numpy as np
import structlog

from rasa.core.brokers.broker import EventBroker
from rasa.core.channels.voice_ready.utils import CallParameters
from rasa.core.channels.voice_stream.audio_bytes import (
    AudioFormat,
    RasaAudioBytes,
)
from rasa.core.channels.voice_stream.call_recording.recording_encoder import (
    RECORDING_FILE_EXTENSION,
    RecordingEncoder,
)
from rasa.core.channels.voice_stream.call_recording.storages import (
    create_recording_storage,
)
from rasa.core.channels.voice_stream.call_recording.storages.base import (
    RecordingReference,
)
from rasa.core.config.available_endpoints import RecordingConfig

logger = structlog.get_logger(__name__)

RECORDING_AVAILABLE_EVENT = "call_recording_available"
RECORDING_FAILED_EVENT = "call_recording_failed"
RECORDING_SKIPPED_EVENT = "call_recording_skipped"

PCM16_DTYPE = "<i2"
_CHANNEL_COLUMNS: Dict[str, int] = {"user": 0, "bot": 1}


@dataclass
class _RecordedChunk:
    channel: Literal["user", "bot"]
    offset_seconds: float
    audio: RasaAudioBytes


class CallRecordingSession:
    """Collect and publish a single voice call recording."""

    def __init__(
        self,
        config: RecordingConfig,
        conversation_id: str,
        call_parameters: CallParameters,
        audio_format: AudioFormat,
        event_broker: Optional[EventBroker],
    ) -> None:
        self.config = config
        self.conversation_id = conversation_id
        self.call_parameters = call_parameters
        self.audio_format = audio_format
        self.event_broker = event_broker
        self.started_at = time.monotonic()
        self._chunks: List[_RecordedChunk] = []
        self._bot_playback_stops: List[float] = []
        self._call_ended = False

    @property
    def started_metadata(self) -> Dict[str, Any]:
        return {
            "enabled": True,
            "call_id": self.call_parameters.call_id,
            "status": "pending",
        }

    def record_user_audio(self, audio: RasaAudioBytes) -> None:
        self._record("user", audio)

    def record_bot_audio(self, audio: RasaAudioBytes) -> None:
        self._record("bot", audio)

    def mark_bot_playback_stopped(self) -> None:
        """Note that bot audio the channel still had buffered was never heard.

        Bot audio is handed to the channel faster than it plays. On barge-in and
        at call teardown the channel drops whatever is left in its buffer, so the
        recording must end the bot leg here instead of at the end of the
        utterance we produced.
        """
        self._bot_playback_stops.append(time.monotonic() - self.started_at)

    def mark_call_ended(self) -> None:
        """End the recording at the moment the caller left the call.

        The agent keeps running for a shutdown grace period and can finish an
        utterance the caller is no longer connected to, so audio produced from
        here on is ignored rather than appended.
        """
        self.mark_bot_playback_stopped()
        self._call_ended = True

    def finalize(self) -> None:
        """Encode, upload, and announce the recording outcome on the event broker.

        SessionStarted metadata keeps ``status: pending`` (tracker is append-only).
        Terminal outcomes are published as broker events: available, failed, or
        skipped. Encode/upload failures are separate from a publish failure after
        a successful upload so an orphaned object is still logged with its URI.
        """
        if not self._chunks:
            logger.info(
                "voice_recording.finalize.skipped_empty",
                call_id=self.call_parameters.call_id,
                conversation_id=self.conversation_id,
            )
            self._publish_recording_skipped()
            return

        try:
            reference = self._encode_and_upload()
        except Exception as exc:
            logger.error(
                "voice_recording.finalize.failed",
                call_id=self.call_parameters.call_id,
                conversation_id=self.conversation_id,
                error=str(exc),
            )
            self._publish_recording_failed(str(exc))
            return

        try:
            self._publish_recording_available(reference)
        except Exception as exc:
            logger.error(
                "voice_recording.finalize.publish_failed",
                call_id=self.call_parameters.call_id,
                conversation_id=self.conversation_id,
                recording_uri=reference.uri,
                error=str(exc),
            )

    def _encode_and_upload(self) -> RecordingReference:
        """Write stereo PCM, encode the recording, and upload to configured storage."""
        with tempfile.TemporaryDirectory() as directory:
            temp_dir = Path(directory)
            pcm_path = temp_dir / "recording.pcm"
            encoded_path = temp_dir / f"recording.{RECORDING_FILE_EXTENSION}"
            self._write_stereo_pcm(pcm_path)
            RecordingEncoder().encode(
                pcm_path, encoded_path, self.audio_format.sample_rate
            )
            return create_recording_storage(self.config).upload(
                encoded_path,
                conversation_id=self.conversation_id,
                call_id=self.call_parameters.call_id,
            )

    def _record(self, channel: Literal["user", "bot"], audio: RasaAudioBytes) -> None:
        if self._call_ended:
            return
        if audio.format != self.audio_format:
            logger.warning(
                "voice_recording.audio_format_mismatch",
                expected_format=self.audio_format,
                actual_format=audio.format,
            )
            return
        self._chunks.append(
            _RecordedChunk(
                channel=channel,
                offset_seconds=time.monotonic() - self.started_at,
                audio=audio,
            )
        )

    def _write_stereo_pcm(self, pcm_path: Path) -> None:
        """Interleave both call legs into one stereo PCM16 timeline."""
        placements = self._plan_placements()
        total_samples = max(
            (start + len(samples) for start, samples, _ in placements), default=0
        )
        stereo = np.zeros((total_samples, 2), dtype=PCM16_DTYPE)
        for start, samples, column in placements:
            stereo[start : start + len(samples), column] = samples

        pcm_path.write_bytes(stereo.tobytes())

    def _plan_placements(self) -> List[Tuple[int, np.ndarray, int]]:
        """Place chunks without overlapping audio from the same call leg.

        Chunks can arrive faster than they play. Append each chunk after the
        previous one on its leg, while preserving real gaps between bursts. Bot
        audio that never reached the caller is cut off.

        Returns:
            Tuples of start sample, PCM16 samples, and stereo column index.
        """
        next_free_sample = dict.fromkeys(_CHANNEL_COLUMNS, 0)
        placements: List[Tuple[int, np.ndarray, int]] = []

        for chunk in self._chunks:
            samples = np.frombuffer(chunk.audio.to_pcm16(), dtype=PCM16_DTYPE)
            arrival_sample = round(chunk.offset_seconds * self.audio_format.sample_rate)
            start = max(arrival_sample, next_free_sample[chunk.channel])
            end = start + samples.size

            stop = self._playback_stop_sample(chunk)
            if stop is not None and stop < end:
                end = max(start, stop)

            next_free_sample[chunk.channel] = end
            if end > start:
                placements.append(
                    (start, samples[: end - start], _CHANNEL_COLUMNS[chunk.channel])
                )

        return placements

    def _playback_stop_sample(self, chunk: _RecordedChunk) -> Optional[int]:
        """Sample at which playback of a bot chunk was cut short, if it was.

        The caller hears a bot chunk only up to the first playback stop that
        happens after we handed the chunk to the channel. Stops recorded before
        that belong to an earlier utterance.
        """
        if chunk.channel != "bot":
            return None
        index = bisect.bisect_left(self._bot_playback_stops, chunk.offset_seconds)
        if index == len(self._bot_playback_stops):
            return None
        return round(self._bot_playback_stops[index] * self.audio_format.sample_rate)

    def _publish_recording_available(self, reference: RecordingReference) -> None:
        # TODO: This publishes straight to event_broker, bypassing
        # TrackerStore.stream_events (honors stream_pii). When stream_pii is
        # false this still emits conversation_id, call_id, and a URI to the
        # full call audio. Same gap in _publish_terminal. Fix later.
        if self.event_broker is None:
            logger.debug(
                "voice_recording.available.no_event_broker",
                call_id=self.call_parameters.call_id,
                conversation_id=self.conversation_id,
                recording_uri=reference.uri,
            )
            return

        self.event_broker.publish(
            {
                "event": RECORDING_AVAILABLE_EVENT,
                "version": "1.0",
                "sender_id": self.conversation_id,
                "conversation_id": self.conversation_id,
                "call_id": self.call_parameters.call_id,
                "recording": {
                    "provider": reference.provider,
                    "bucket": reference.bucket,
                    "key": reference.key,
                    "uri": reference.uri,
                    "content_type": reference.content_type,
                    "status": reference.status,
                },
            }
        )

    def _publish_recording_failed(self, error: str) -> None:
        """Publish that recording could not be encoded or uploaded."""
        self._publish_terminal(
            RECORDING_FAILED_EVENT,
            status="failed",
            publish_error_event="voice_recording.failed.publish_failed",
            error=error,
        )

    def _publish_recording_skipped(self) -> None:
        """Publish that recording was enabled but no audio was captured."""
        self._publish_terminal(
            RECORDING_SKIPPED_EVENT,
            status="skipped",
            publish_error_event="voice_recording.skipped.publish_failed",
        )

    def _publish_terminal(
        self,
        event_name: str,
        status: str,
        publish_error_event: str,
        error: Optional[str] = None,
    ) -> None:
        """Best-effort broker publish for a non-available terminal outcome.

        Publish failures here must not raise; they would obscure the original
        finalize failure that triggered this path.
        """
        if self.event_broker is None:
            return

        payload: Dict[str, Any] = {
            "event": event_name,
            "version": "1.0",
            "sender_id": self.conversation_id,
            "conversation_id": self.conversation_id,
            "call_id": self.call_parameters.call_id,
            "recording": {"status": status},
        }
        if error is not None:
            payload["error"] = error

        try:
            self.event_broker.publish(payload)
        except Exception as exc:
            logger.error(
                publish_error_event,
                call_id=self.call_parameters.call_id,
                conversation_id=self.conversation_id,
                error=str(exc),
            )


def create_call_recording_session(
    config: Optional[RecordingConfig],
    conversation_id: str,
    call_parameters: CallParameters,
    audio_format: AudioFormat,
    event_broker: Optional[EventBroker],
) -> Optional[CallRecordingSession]:
    if config is None or not config.enabled:
        return None
    return CallRecordingSession(
        config=config,
        conversation_id=conversation_id,
        call_parameters=call_parameters,
        audio_format=audio_format,
        event_broker=event_broker,
    )
